pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        // ensure caddress is not C itself to avoid trivial recursion issues
        vm.assume(caddress != address(c));
        // restrict lengths to avoid 'vm.assume rejected too many inputs' and huge loop gas
        vm.assume(_tos.length <= 10);
        for (uint i = 0; i < _tos.length; i++) {
            // ensure we don't transfer to zero address to avoid common reverts masking the difference
            vm.assume(_tos[i] != address(0));
        }

        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool res) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: always returns true (never reverts) for admissible inputs because require(_s) ensures all sub-calls succeed
        // Mutant: may revert or succeed despite failing sub-calls; invariant broken if it reverts when reference succeeds
        assertTrue(ok);
    }
}

