// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        // Restrict to valid input domain: arrays must have matching lengths and be non-empty
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Restrict lengths to a manageable range
        uint256 len = _tos.length;
        len = bound(len, 1, 50);
        // Resize arrays to actual length
        address[] memory tos = new address[](len);
        uint256[] memory vals = new uint256[](len);
        for (uint256 i = 0; i < len; i++) {
            tos[i] = _tos[i];
            vals[i] = v[i];
        }

        // Call the transfer function and observe revert/success behavior
        bool ok = false;
        try c.transfer(from, caddress, tos, vals) returns (bool result) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: reference C reverts (ok == false) when any inner call fails.
        // Since we cannot force an inner failure without controlling the external contract,
        // we assert that the reference succeeds (ok == true) for all admissible inputs that do not cause inner failure.
        // To make the bug observable, we must ensure the external call can fail.
        // We'll use address(c) as caddress to intentionally cause a failure (C has no transferFrom).
        // This makes the reference revert and the mutant succeed, breaking the rule.
        assertTrue(ok == true);
    }
}
